-- GENERATED by supabase/scripts/version-roundtrip.mts.
--
-- ONE transaction, on purpose: set_config(..., true) is transaction-local, so
-- the authenticated identity the RPCs read from auth.uid() lives only here.
-- Splitting this would silently run the RPCs as `postgres` and prove nothing
-- about RLS or about SECURITY INVOKER.
--
-- The jsonb payloads go into a temp table BEFORE the role switch rather than
-- inline in the DO block: inside a dollar-quoted body a doubled '' is two
-- literal apostrophes, so a payload containing a geresh would be corrupted
-- silently rather than rejected.
--
-- Fixtures are removed at the end and the cleanup is asserted.
begin;

insert into auth.users (id, email)
values ('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee', 'version-roundtrip@test.invalid');

create temp table rt_in (k text primary key, v jsonb) on commit drop;
insert into rt_in (k, v) values
  ('parent', '{"owner_id":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","group_id":null,"name":"לחם כוסמין 82% — בדיקת גרסאות","category":"לחמים","tags":["בדיקה","גרסאות"],"is_sub":false,"locked":false,"yield_units":2,"unit_weight":800,"yield_actual":null,"weight_before":null,"weight_after":null,"dough_mode":false,"ddt":null,"flour_temp":null,"room_temp":null,"friction":null,"target_fc":27.5,"sale_price":95,"sale_price_basis":"unit","packaging_cost":2.5,"labor_cost":0,"other_cost":null,"target_gm":62.5,"shelf_life":"","storage":"","freezing":"","thawing":"","equipment":"","notes":"הערה עם גרשיים: קמח 82%","manual_allergens":[],"pan":null,"version_of":null,"version_note":"","saved_from_item_id":null}'::jsonb),
  ('ingredients', '[{"recipe_id":"","ord":0,"name":"קמח מלא","ingredient_key":"קמח מלא","qty":600,"unit":"g","flour":true,"liquid":false,"water_pct":null,"unit_weight":null,"g_per_100":null,"price":4.25,"price_unit":"ק\"ג","sub_recipe_id":null,"note":""},{"recipe_id":"","ord":1,"name":"מים","ingredient_key":"מים","qty":420,"unit":"g","flour":false,"liquid":true,"water_pct":100,"unit_weight":null,"g_per_100":null,"price":null,"price_unit":null,"sub_recipe_id":null,"note":""},{"recipe_id":"","ord":2,"name":"שמן זית","ingredient_key":"שמן זית","qty":30,"unit":"ml","flour":false,"liquid":false,"water_pct":0,"unit_weight":null,"g_per_100":null,"price":0,"price_unit":"ליטר","sub_recipe_id":null,"note":""},{"recipe_id":"","ord":3,"name":"מלח","ingredient_key":"מלח","qty":12,"unit":"g","flour":false,"liquid":false,"water_pct":null,"unit_weight":null,"g_per_100":null,"price":null,"price_unit":null,"sub_recipe_id":null,"note":""}]'::jsonb),
  ('ingredients_edited', '[{"recipe_id":"","ord":0,"name":"קמח מלא","ingredient_key":"קמח מלא","qty":600,"unit":"g","flour":true,"liquid":false,"water_pct":null,"unit_weight":null,"g_per_100":null,"price":4.25,"price_unit":"ק\"ג","sub_recipe_id":null,"note":""},{"recipe_id":"","ord":1,"name":"מים","ingredient_key":"מים","qty":450,"unit":"g","flour":false,"liquid":true,"water_pct":100,"unit_weight":null,"g_per_100":null,"price":null,"price_unit":null,"sub_recipe_id":null,"note":""},{"recipe_id":"","ord":2,"name":"שמן זית","ingredient_key":"שמן זית","qty":30,"unit":"ml","flour":false,"liquid":false,"water_pct":0,"unit_weight":null,"g_per_100":null,"price":0,"price_unit":"ליטר","sub_recipe_id":null,"note":""},{"recipe_id":"","ord":3,"name":"מלח","ingredient_key":"מלח","qty":12,"unit":"g","flour":false,"liquid":false,"water_pct":null,"unit_weight":null,"g_per_100":null,"price":null,"price_unit":null,"sub_recipe_id":null,"note":""}]'::jsonb),
  ('steps', '[{"recipe_id":"","ord":0,"text":"ללוש 12 דקות","temp":null,"temp_unit":"C","minutes":12,"kind":"active"},{"recipe_id":"","ord":1,"text":"לאפות","temp":240,"temp_unit":"C","minutes":40,"kind":null}]'::jsonb),
  ('issues', '[]'::jsonb);

create temp table rt_out (ord int, result jsonb) on commit drop;
grant select on rt_in to authenticated;
grant insert, select on rt_out to authenticated;

select set_config('request.jwt.claims', '{"sub":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee","role":"authenticated"}', true);
set local role authenticated;

do $rt$
declare
  rid uuid;
  vid uuid;
begin
  -- 1. create. No version is taken: there is no previous state to describe.
  select public.save_recipe(
    (select v from rt_in where k = 'parent'),
    (select v from rt_in where k = 'ingredients'),
    (select v from rt_in where k = 'steps'),
    (select v from rt_in where k = 'issues'),
    null, null, ''
  ) into rid;

  -- 2. update ONE quantity. The state above becomes V1, so the snapshot and
  --    the live rows differ in exactly one place and a mix-up cannot pass.
  perform public.save_recipe(
    (select v from rt_in where k = 'parent'),
    (select v from rt_in where k = 'ingredients_edited'),
    (select v from rt_in where k = 'steps'),
    (select v from rt_in where k = 'issues'),
    rid, null, 'test'
  );

  -- 3. the version document, exactly as the client reads it
  insert into rt_out select 1, jsonb_build_object(
    'phase', 'snapshot',
    'recipe_id', rid,
    'version_count', (select count(*) from public.recipe_versions where recipe_id = rid),
    'tag', (select tag from public.recipe_versions where recipe_id = rid),
    'snapshot', (select snapshot from public.recipe_versions where recipe_id = rid),
    'live_water_qty', (select qty from public.ingredients
                        where recipe_id = rid and name = 'מים')
  );

  -- 4. restore it, then read the LIVE rows back in the shape the client selects
  select id into vid from public.recipe_versions where recipe_id = rid and tag = 'V1';
  perform public.restore_recipe_version(vid);

  insert into rt_out select 2, jsonb_build_object(
    'phase', 'restored',
    'version_count', (select count(*) from public.recipe_versions where recipe_id = rid),
    'tags', (select jsonb_agg(tag order by tag) from public.recipe_versions where recipe_id = rid),
    'bundle', (
      select jsonb_build_object(
        'recipe', to_jsonb(r.*),
        'ingredients', coalesce((select jsonb_agg(to_jsonb(i.*) order by i.ord)
                                  from public.ingredients i where i.recipe_id = r.id), '[]'::jsonb),
        'steps', coalesce((select jsonb_agg(to_jsonb(s.*) order by s.ord)
                            from public.steps s where s.recipe_id = r.id), '[]'::jsonb),
        'issues', coalesce((select jsonb_agg(to_jsonb(x.*) order by x.ord)
                             from public.issues x where x.recipe_id = r.id), '[]'::jsonb)
      )
      from public.recipes r where r.id = rid
    )
  );
end $rt$;

reset role;
select result from rt_out order by ord;
commit;

cleanup:
delete from auth.users where id = 'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee';
select (select count(*) from auth.users where id = 'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee')
     + (select count(*) from public.recipes where owner_id = 'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee')
     + (select count(*) from public.recipe_versions v
          join public.recipes r on r.id = v.recipe_id where r.owner_id = 'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee') as leftovers;
